class Solution:
    def findNumberOfLIS(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i] = (length of longest increasing subsequence ending at i, number of such subsequences)
        dp = [(1, 1) for _ in range(n)]

        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i]:
                    # Update dp[i] if a longer subsequence is found
                    if dp[j][0] + 1 > dp[i][0]:
                        dp[i] = (dp[j][0] + 1, dp[j][1])
                    elif dp[j][0] + 1 == dp[i][0]:
                        # Add the number of subsequences from j to i
                        dp[i] = (dp[i][0], dp[i][1] + dp[j][1])

        # Find the maximum length of LIS
        max_len = max(length for length, count in dp)
        # Sum the counts of all subsequences with max length
        result = sum(count for length, count in dp if length == max_len)

        return result
