class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        # If the total number of flowers is less than required for m bouquets
        if len(bloomDay) < m * k:
            return -1

        # Binary search between the minimum and maximum bloom day
        left, right = min(bloomDay), max(bloomDay)

        def canMakeBouquets(day: int) -> bool:
            bouquets = 0
            consecutive = 0
            for d in bloomDay:
                if d <= day:
                    consecutive += 1
                    if consecutive >= k:
                        bouquets += 1
                        consecutive = 0
                else:
                    consecutive = 0
                if bouquets >= m:
                    return True
            return False

        while left < right:
            mid = (left + right) // 2
            if canMakeBouquets(mid):
                right = mid
            else:
                left = mid + 1

