class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)
        count = 0

        # Precompute the comparison values for the nums array
        comparisons = []
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                comparisons.append(1)
            elif nums[i + 1] == nums[i]:
                comparisons.append(0)
            else:
                comparisons.append(-1)

        # Slide window over the comparisons array
        for i in range(len(comparisons) - m + 1):
            match = True
            for j in range(m):
                if comparisons[i + j] != pattern[j]:
                    match = False
                    break
            if match:
                count += 1

        return count
